(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zk-sj-prepa-ped-j3-idesfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zk-sj-prepa-ped-j3-idesfm\",\n \"titre\": \"Préparation D.E (J) · J3 Pédiatrie IDE/SFM\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 55,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n   \"sha256\": \"45110ca169c7b815e8c5983cb6aa915440763cce1306bb015109584afb42df7f\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Pédiatrie · Prépa D.E J3 (IDE/SFM)\",\n     \"slug\": \"prepa-ped-j3-idesfm\",\n     \"pages\": \"\",\n     \"count\": 55,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Pédiatrie\",\n     \"source\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Nouveau-né GG, sexe masculin, est âgé de 5 jours. Il vit avec sa mère à Grand Yapo. La mère réalise les soins du cordon avec une décoction de plante traditionnelle. L'examen somatique de GG est normal. La réalité personnelle de GG comporte :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"données de dépendance\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"5 données de dépendance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3 données de dépendance\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"2 données de dépendance\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 2 données de dépendance\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'examen étant normal, on ne retient que deux éléments de dépendance : le très jeune âge (5 jours : le nouveau-né dépend entièrement de sa mère, source de difficulté « manque de force ») et les soins du cordon par décoction traditionnelle (danger d'infection et de tétanos ombilical, lié à un manque de connaissance de la mère). Les autres données (sexe, lieu de vie, examen normal) sont des données d'indépendance. Remarque : Dans le sujet, la première option n'indique pas de nombre.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Introduction au raisonnement clinique — Diagnostic infirmier (Analyse et interprétation des données) ; Nouveau-né normal — Rôles de soins après la naissance\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'échographie réalisée au premier trimestre de la grossesse vise les objectifs suivants sauf un. Cocher l'intrus.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Confirmer la grossesse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Estimer le risque trisomie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Apprécier l'activité cardiaque de l'embryon\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Rechercher des malformations\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Rechercher des malformations\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'échographie du 1er trimestre (11-13 SA) confirme la grossesse évolutive, la date, l'activité cardiaque et le nombre d'embryons, et mesure la clarté nucale (risque de trisomie 21). La recherche systématique des malformations est le but de l'échographie morphologique du 2e trimestre (vers 22 SA). (explication hors cours du projet) Remarque : Certaines grosses malformations peuvent déjà être vues au 1er trimestre, mais ce n'est pas l'objectif principal de cet examen.\\n\\nSource : Explication hors cours du projet (aucun chapitre sur l'échographie obstétricale dans les cours de pédiatrie)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les signes suivants sont ceux du kwashiorkor sauf un. Lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Enfant grognon\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ulcération et desquamation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Alopécie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Bouffissure du visage\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Alopécie\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Dans le kwashiorkor, l'enfant est hostile, pleurnichard et grognon ; il a une bouffissure du visage, des œdèmes, des ulcérations et desquamations (aspect de grand brûlé). Les cheveux sont altérés (secs, fins, cassants puis roux) mais l'alopécie fait partie des signes du marasme.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Malnutrition de l'enfant — Diagnostic positif (Kwashiorkor ; Formes cliniques : Marasme)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les cellules qui produisent le lait maternel sont appelées :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Cellules souches\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Cellule épidermique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Cellules épithéliales\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Cellules myoépithéliales\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Cellules épithéliales\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le lait est sécrété par les cellules glandulaires qui tapissent les alvéoles (acini) du sein : ce sont des cellules épithéliales sécrétoires (stimulées par la prolactine). Les cellules myoépithéliales entourent les alvéoles et se contractent sous l'effet de l'ocytocine : elles assurent l'éjection du lait, pas sa production. Remarque : Le terme « épithéliales » ne figure pas mot à mot dans les cours (ils parlent de cellules glandulaires des alvéoles) ; la précision sur les cellules myoépithéliales est hors cours.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Allaitement maternel — Physiologie de la lactation (Anatomie du sein ; Production du lait) ; Cours de santé infantile L1 IDE-SFM, Allaitement — Anatomie du sein\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"BH est âgé de 2 ans et pèse 12 kg. Il est correctement nourri. Sa surface corporelle est estimée à :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"0,2 m2\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"0,4 m2\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"0,5 m2\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"0,6 m2\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 0,5 m2\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Avec la formule (4P + 7) / (P + 90), pour P = 12 kg : (48 + 7) / 102 ≈ 0,54 m², soit environ 0,5 m². Cela concorde avec les repères du cours : 0,2 m² à la naissance, 0,4 m² à 9 mois, 0,6 m² à 3 ans. Remarque : La formule de calcul est hors cours ; le cours donne seulement les repères 0,2 / 0,4 / 0,6 m².\\n\\nSource : Cours de santé infantile L1 IDE-SFM, Mensurations — Tableau récapitulatif des repères normaux de la croissance (colonne SC)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'infection bactérienne du nouveau-né précoce survient entre :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"0 et 7 jours\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"7 et 8 jours\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"8 et 16 jours\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"16 et 28 jours\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 0 et 7 jours\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"On distingue l'infection précoce ou materno-fœtale, qui survient avant le 7e jour de vie, et l'infection tardive ou post-natale, qui survient après le 7e jour (jusqu'à J28).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Infections bactériennes du nouveau-né — Introduction (Définition) ; Néonatologie (module de formation), Infections néonatales — Définition\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous collaborez à la réalisation des examens suivants en cas de fièvre aiguë, sauf un lequel :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hémoculture\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"ECBU\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Analyse LCR\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Sérodiagnostic de Widal et Félix\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Sérodiagnostic de Widal et Félix\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Devant une fièvre aiguë mal tolérée, on demande la goutte épaisse/frottis, la NFS, la glycémie, la radiographie pulmonaire, l'analyse du LCR (signes neurologiques) et l'ECBU (signes urinaires), avec l'hémoculture si on suspecte une infection bactérienne. Le sérodiagnostic de Widal et Félix est réservé à la fièvre prolongée (recherche de fièvre typhoïde). Remarque : L'hémoculture n'est pas citée mot à mot dans la liste « fièvre mal tolérée » du cours.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Fièvre de l'enfant — Diagnostic étiologique (Prescription d'examens : fièvre mal tolérée / fièvre prolongée)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un enfant qui fait de la fièvre avec une bonne tolérance présente :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une conscience altérée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Des marbrures\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un faciès vultueux\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Un teint grisâtre\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Un faciès vultueux\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les signes de mauvaise tolérance de la fièvre sont : pâleur, cyanose péribuccale, cri plaintif, extrémités froides, marbrures, teint grisâtre, temps de recoloration cutanée allongé et altération de la conscience. Un visage rouge et chaud (faciès vultueux) traduit une fièvre bien tolérée. Remarque : « Faciès vultueux » n'est pas écrit mot à mot dans le cours ; il s'oppose aux signes de mauvaise tolérance cités.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Fièvre de l'enfant — Diagnostic étiologique (Examen physique : signes de mauvaise tolérance)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une femme rhésus négatif accouche d'un enfant rhésus positif. Elle n'a pas eu le sérum anti-D. Dans une telle situation le nouveau-né :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Doit téter les seins comme les autres enfants\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ne doit pas téter les seins comme les autres enfants\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Doit être nourri au biberon\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Doit recevoir le sérum anti tétanique en sous cutané\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Ne doit pas téter les seins comme les autres enfants\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Ne doit pas téter les seins ». Le cours dit seulement qu'il faut administrer le sérum anti-D à la mère rhésus négatif dans les 72 heures qui suivent l'accouchement d'un bébé rhésus positif, pour protéger la grossesse suivante (incompatibilité fœto-maternelle rhésus).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Ictère du nouveau-né — Rôles préventifs ; Cours de santé infantile L1 IDE-SFM, Examen du nouveau-né — Besoin de manger et boire\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les facteurs de risques de survenue des convulsions, liés à l'enfant sont les suivants, sauf un, lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Faible poids de naissance\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Céphalhématome\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Traumatisme crânien\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Malnutrition\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Céphalhématome\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les facteurs favorisants des convulsions sont la souffrance cérébrale néonatale, l'ictère nucléaire, l'infection néonatale, les séquelles neurologiques de maladies (méningite, neuropaludisme, malnutrition), la fièvre élevée et les antécédents familiaux. Le céphalhématome est une collection de sang sous le périoste, bénigne, qui ne touche pas le cerveau : il n'expose pas aux convulsions. Remarque : Le faible poids de naissance et le traumatisme crânien ne figurent pas mot à mot dans la liste du cours.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Convulsions de l'enfant — Épidémiologie (Facteurs favorisants) ; Traumatismes obstétricaux — Céphalhématome\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les rôles de collaboration dans la prise en charge des convulsions sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Administrer le diazépam\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Récupérer des résultats de laboratoire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Prendre une voie veineuse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Aider la mère à allaiter\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Administrer le diazépam\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le diazépam (0,5 mg/kg en intrarectal ou IV lente) est administré pour arrêter la crise : c'est un médicament, donc un soin réalisé sur prescription (rôle délégué ou de collaboration). Aider la mère à allaiter est un rôle propre. Remarque : La prise d'une voie veineuse est elle aussi faite « sur indication médicale » dans le cours ; la question n'accepte qu'une seule réponse.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Convulsions de l'enfant — Rôle de soins curatifs ; Introduction au raisonnement clinique — Plan de soins (Interventions)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"ML est âgé de 36 mois, sa mère l'amène aux urgences pour une diarrhée glaireuse. Le germe probable à l'origine de cette diarrhée est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Schigelles\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Eschérichia coli\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Vibrion cholérique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Rotavirus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Schigelles\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les shigelles agissent par mécanisme invasif : elles détruisent l'entérocyte et donnent des selles glaireuses ou glairo-sanglantes (dysenterie). Le vibrion cholérique agit par mécanisme toxinique (selles liquides abondantes) et le rotavirus donne surtout des selles liquides. Remarque : Le cours cite aussi l'Escherichia coli entéro-invasif parmi les germes invasifs ; les shigelles restent le germe typique de la diarrhée glaireuse.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Étiopathogénie (Étiologie ; Pathogénie : mécanisme invasif)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La mère de JK n'a pas respecté la prescription médicale, et il présente 4 jours plus tard un poids de 8 kg, les yeux enfoncés, la bouche sèche et des signes évidents de déshydratation. Quelle est la quantité de SRO à administrer :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"500 ML\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"400 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"600 ml\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"700ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 600 ml\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Des signes évidents de déshydratation relèvent du plan B : 75 ml/kg de SRO en 4 heures au centre de santé. Pour 8 kg : 8 × 75 = 600 ml.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, Plan B : traiter les signes évidents de déshydratation ; L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Rôles curatifs (Plan B)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La diarrhée aiguë concerne l'émission d'au moins 3 selles liquides par 24 heures depuis moins de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"21 jours\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"14 jours\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"10 jours\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"8 jours\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 14 jours\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La diarrhée aiguë dure depuis moins de 14 jours ; au-delà de 14 jours, on parle de diarrhée persistante.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Introduction (Définition et limite du thème)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le plan de traitement des signes sévères de déshydratation est le :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Plan A\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Plan B\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Plan C\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Plan D\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Plan C\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Pas de déshydratation : plan A ; signes évidents : plan B ; signes sévères : plan C (réhydratation par voie veineuse au Ringer lactate, à l'hôpital).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Diagnostic de gravité (Tableau n°1 : classification)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"DG est incapable de nouer les lacets de sa paire de tennis mais s'habille seul et raconte de petites histoires. Je conclus que DG est âgé de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"2 ans\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"3 ans\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"4 ans\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"5 ans\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 4 ans\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"À 4 ans, l'enfant s'habille seul sauf les lacets des chaussures et commence à raconter des histoires. À 3 ans, il a encore besoin d'aide pour les boutons ; il lace ses chaussures à partir de 6 ans.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Annexes — Normes physiologiques de l'enfant (Tableau II : principales étapes du développement psychomoteur)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les propositions suivantes concernent les signes d'un enfant souffrant de marasme. Cochez la proposition qui est retrouvée au stade de début de cette maladie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Fonte graisseuse et musculaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Retard pondéral inférieur à 60% du poids idéal théorique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Affamé et porte le doigt à la bouche\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Alopécie avec le reste des cheveux normaux non décolorés\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Affamé et porte le doigt à la bouche\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Au début du marasme, la croissance stagne et l'enfant est affamé, il porte ses doigts à la bouche, crie ou pleure sans cesse. La fonte graisseuse et musculaire, le retard pondéral < 60 % du poids idéal et l'alopécie sont des signes de la phase d'état.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Malnutrition de l'enfant — Formes cliniques (Marasme : signes cliniques)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les propositions suivantes sont relatives à la bonne pratique de la réanimation du nouveau-né en salle de naissance sauf une. Cocher cette proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Essuyer l'enfant\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Vérifier la respiration\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Porter un bonnet\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Pincer le mamelon\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Pincer le mamelon\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Pincer le mamelon pour faire crier le bébé est un geste de brutalité à proscrire : il favorise l'inhalation du liquide amniotique et le stress peut provoquer un ulcère avec hémorragie digestive. Essuyer, vérifier la respiration et mettre un bonnet (contrôle de la température) font partie de la bonne pratique.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Réanimation du nouveau-né en salle de naissance — Gestes dangereux à proscrire\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les séquelles neurologiques et neurosensorielles au cours du paludisme sont les suivantes sauf une, laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Paralysie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Troubles du tonus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Myosite\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hypoacousie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Myosite\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Après une forme neurologique, environ 10 % des enfants guéris gardent des séquelles : surdité (ou hypoacousie), aphasie, paralysie, troubles du tonus, difficultés scolaires. La myosite (atteinte du muscle) n'est pas une séquelle neurologique du paludisme.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Paludisme de l'enfant — Problèmes et devenir (Devenir)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le paludisme grave est causé par l'espèce plasmodiale suivante :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vivax\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ovale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Knowlésie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Falciparum\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Falciparum\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Parmi les espèces de Plasmodium, seul Plasmodium falciparum est responsable des formes graves ; il représente près de 98 % des cas en Côte d'Ivoire.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Paludisme de l'enfant — Introduction (Définition)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les facteurs de mauvais pronostic au cours de la méningite purulente sont les suivants, sauf un lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Âge de moins de 5 ans\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Virulence du germe\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Malnutrition\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Retard de diagnostic et prise en charge\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Malnutrition\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Malnutrition » comme intrus. Les éléments de mauvais pronostic du cours sont : le très jeune âge, la nature du germe (pneumocoque et Haemophilus les plus virulents), un traitement antérieur, l'existence de facteurs favorisants, le retard au diagnostic et les complications.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Méningites bactériennes de l'enfant — Épidémiologie (Facteurs favorisants et de gravité) ; Problèmes et devenir (Devenir)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les principaux virus responsables des infections respiratoires aiguës sont les suivants, sauf un, lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Virus para influenzae\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Herpès simplex virus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Rhinovirus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Virus respiratoire syncytial\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Virus respiratoire syncytial\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Virus respiratoire syncytial ». Le cours cite comme virus fréquents des IRA : le virus para-influenzae, le virus respiratoire syncytial (VRS) et le rhinovirus.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Infections respiratoires aiguës de l'enfant — Épidémiologie (Germes)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Ces affirmations concernant la bronchiolite sont justes sauf une. Laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Causée par Virus respiratoire Syncitial\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Respiration sifflante\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fièvre et rhume\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Plus fréquent après 2 ans\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Causée par Virus respiratoire Syncitial\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient a. Le cours décrit la bronchiolite comme une maladie du nourrisson (1 mois à 2 ans), due au VRS, avec toux, polypnée, wheezing (respiration sifflante), râles, fièvre modérée et rhume.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Infections respiratoires aiguës de l'enfant — Principales formes étiologiques des IRA basses (Bronchiolite)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la prise en charge de la bronchiolite, l'agent de santé a pour rôle propre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Conseils à la mère sur l'hygiène\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Montrer la technique de la DRP à la mère\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Accompagner l'enfant en ORL\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Administrer antipyrétique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Montrer la technique de la DRP à la mère\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Laver les fosses nasales au sérum physiologique (désobstruction rhinopharyngée, DRP) est un geste que l'agent de santé fait et enseigne à la mère sans prescription : c'est un rôle propre. Administrer un antipyrétique est un soin délégué ; accompagner en ORL relève de la collaboration. Remarque : Les conseils d'hygiène relèvent aussi du rôle propre (rôle préventif) ; la question n'accepte qu'une seule réponse.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Rhinopharyngite de l'enfant — Rôles curatifs ; Introduction au raisonnement clinique — Plan de soins (Interventions)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les infections respiratoires basses sont les suivantes sauf une laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Bronchiolite aiguë\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Sinusite maxillaire aiguë\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Laryngite aiguë\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Bronchite aiguë\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Sinusite maxillaire aiguë\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les IRA basses touchent les bronches (bronchite), les bronchioles (bronchiolite) et le poumon (pneumopathie). La sinusite atteint les voies aériennes supérieures : c'est une IRA haute. Remarque : Selon le cours, la laryngite (c) est elle aussi une IRA haute : le sujet comporte donc deux intrus possibles.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Infections respiratoires aiguës de l'enfant — Introduction (Définition)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'administration de zinc comprimé dans le traitement de la diarrhée chez le nourrisson de moins de 6 mois est de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"10 mg/j pendant 7 jours\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"15 mg/j pendant 10 jours\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"10 mg/j pendant 5 jours\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"15 mg/j pendant 7 jours\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 10 mg/j pendant 5 jours\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « 10 mg/j pendant 5 jours ». Le comprimé de zinc est dosé à 20 mg : avant 6 mois on donne ½ comprimé par jour, soit 10 mg/j.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, Plan A : Donner du zinc ; L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Rôles curatifs (Médicaments)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La quantité de SRO à administrer chez un nourrisson, après chaque selle molle dans le plan A de traitement est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"50-100 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"25-50 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"100-200 ml\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Autant qu'il en voudra\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 50-100 ml\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Plan A : jusqu'à 2 ans, 50 à 100 ml de SRO après chaque selle liquide (½ à 1 louche) ; à partir de 2 ans, 100 à 200 ml.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, Plan A : traiter la diarrhée à domicile (Montrer à la mère quelle quantité de liquide donner)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les soins propres dans la prise en charge des vomissements chez l'enfant sont les suivants, sauf un, lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Nettoyer l'enfant\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Aider à alimenter l'enfant\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Administrer du vogalène\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Surveiller l'enfant\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Administrer du vogalène\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le Vogalène (métopimazine) est un antiémétique : c'est un médicament, donc un soin délégué sur prescription. Nettoyer, aider à alimenter et surveiller l'enfant sont des soins propres.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Vomissements de l'enfant — Rôles de soins (Rôles curatifs : antiémétisants)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Tous les facteurs suivants inhibent le réflexe ocytocique chez la mère, sauf un. Cocher l'intrus\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La vue de son bébé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La douleur physique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le manque de confiance en soi\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La crise d'anxiété\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Le manque de confiance en soi\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Le manque de confiance en soi ». Le cours explique que la sécrétion d'ocytocine (éjection du lait) est favorisée par un climat de confiance et la sérénité de la mère ; le stress, la douleur et l'anxiété la freinent.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Allaitement maternel — Physiologie de la lactation (Excrétion et éjection du lait) ; Cours de santé infantile L1 IDE-SFM, Allaitement — Physiologie de la lactation (Après l'accouchement)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'enfant expatrié, venant pour la première fois dans une zone endémique est à risque de faire le paludisme\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le voyageur non immun qui arrive dans une zone de forte endémicité fait partie des facteurs favorisants du paludisme : il n'a pas de prémunition.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Paludisme de l'enfant — Étiopathogénie (Facteurs favorisants)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un encombrement de l'arbre respiratoire au niveau de la zone de conduction se manifeste par une perturbation au niveau des échanges gazeux\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La zone de conduction (nez, trachée, bronches) amène l'air jusqu'aux alvéoles. Si elle est encombrée, moins d'air arrive aux alvéoles : la ventilation alvéolaire baisse et les échanges gazeux sont perturbés (hypoxie). (explication hors cours du projet) Remarque : Les échanges gazeux eux-mêmes se font dans la zone respiratoire (alvéoles) ; ils sont perturbés de façon indirecte.\\n\\nSource : Explication hors cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__31\",\n       \"num\": \"32\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le paracétamol est administré à la posologie de 15 mg par kilogramme toutes les 6 heures si fièvre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le paracétamol se donne à 60 mg/kg/j en 4 prises, soit 15 mg/kg toutes les 6 heures.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Fièvre de l'enfant — Rôles curatifs (Normalisation de la température : moyens médicamenteux)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__32\",\n       \"num\": \"33\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'anorexie du nourrisson est un trouble du comportement alimentaire consécutif à une cause organique\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'anorexie du nourrisson est un trouble du comportement (refus de s'alimenter) d'origine relationnelle ; le diagnostic n'est retenu qu'après avoir éliminé toutes les causes organiques et les erreurs diététiques.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Anorexie du nourrisson — Introduction (Définition)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__33\",\n       \"num\": \"34\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le sevrage précoce est un facteur favorisant la survenue de l'anémie\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Parmi les facteurs favorisants de l'anémie liés à l'environnement, le cours cite l'alimentation par les substituts du lait maternel et les erreurs diététiques de la diversification et du sevrage. Le lait maternel contient du fer mieux absorbé. Remarque : Le texte du cours est partiellement illisible à cet endroit (OCR).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Anémie aiguë de l'enfant — Étiopathogénie (Facteurs favorisants liés à l'environnement)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__34\",\n       \"num\": \"35\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La pose d'une transfusion sanguine est un rôle de collaboration\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La transfusion est faite sur indication médicale : l'agent de santé prélève le groupe sanguin, fait le test de compatibilité au lit du malade, calcule le débit et surveille l'enfant en lien avec le médecin.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Anémie aiguë de l'enfant — Rôle de soins curatifs (3e situation)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson allaité qui émet 3 à 4 selles par jour souffre d'une diarrhée aiguë\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le nourrisson nourri au sein émet normalement plusieurs selles molles par jour (jusqu'à 6 à 7) : ce sont de fausses diarrhées à ne pas confondre avec une diarrhée aiguë.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Diagnostic différentiel\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__36\",\n       \"num\": \"37\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une fièvre qui évolue depuis 15 jours est une fièvre prolongée\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Fièvre aiguë : moins d'une semaine ; fièvre prolongée : plus d'une semaine et moins d'un mois ; au-delà d'un mois : fièvre au long cours ou chronique.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Fièvre de l'enfant — Introduction (Définition)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__37\",\n       \"num\": \"38\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laisser l'enfant avec sa mère 10 heures par jour est l'une des conditions de l'initiative Hôpitaux Amis des Bébés (IHAB)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La 7e règle de l'IHAB est de laisser l'enfant avec sa mère 24 heures sur 24 (cohabitation), et non 10 heures par jour.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Allaitement maternel — Politique de l'allaitement (Dix règles de l'IHAB)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__38\",\n       \"num\": \"39\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'électrophorèse de l'hémoglobine fait partie du bilan prénatal recommandé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le bilan prénatal recommandé comprend le groupe sanguin rhésus, le test d'Emmel et l'électrophorèse de l'hémoglobine (dépistage de la drépanocytose), le VDRL/TPHA, la glycémie et la sérologie VIH.\\n\\nSource : Néonatologie (module de formation), Soins essentiels aux nouveau-nés — Soins maternels (Pendant la grossesse) ; Cours de santé infantile L1 IDE-SFM, Carnet de santé mère-enfant — Antécédents de la mère\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__39\",\n       \"num\": \"40\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson allaité qui émet 3 à 4 selles par jour souffre d'une diarrhée aiguë\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Même réponse qu'à la question précédente identique : chez le nourrisson au sein, plusieurs selles molles par jour sont normales (fausse diarrhée). Remarque : Cette question figure deux fois dans le sujet.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Diagnostic différentiel\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__40\",\n       \"num\": \"41\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La lèvre inférieure du bébé éversée et l'aréole peu visible en haut est un critère de bon positionnement au sein\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Ce sont les critères d'une bonne prise du sein (bouche grande ouverte, menton contre le sein, lèvre inférieure éversée, aréole plus visible en haut). Les critères de bon positionnement sont différents : dos du bébé sur l'avant-bras de la mère, nuque sur le pli du coude, ventre contre ventre, bouche face au mamelon.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Allaitement maternel — Aide et conseils à l'allaitement (Aide à l'allaitement)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__41\",\n       \"num\": \"42\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le surfactant est un film tensioactif sécrété par les cellules pneumocytes I des poumons\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le surfactant est une substance lipido-protidique produite par les pneumocytes de type II (et non I), à partir de 22 SA, en quantité suffisante vers 36 SA. Son déficit cause la maladie des membranes hyalines.\\n\\nSource : Néonatologie (module de formation), Adaptation à la vie extra-utérine — Adaptation respiratoire (Sécrétion du surfactant)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__42\",\n       \"num\": \"43\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'entérocolite est un problème lié à la prématurité\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'entérocolite ulcéro-nécrosante fait partie des complications digestives de la prématurité ; elle est favorisée par le faible âge gestationnel et le retard de croissance intra-utérin.\\n\\nSource : Néonatologie (module de formation), Prématurité — Complications immédiates (Complications digestives : ECUN)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__43\",\n       \"num\": \"44\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le manque de soutien psychologique de la mère est un facteur de déclin de l'allaitement exclusif\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours cite parmi les facteurs de déclin de l'allaitement : la promotion des laits infantiles, l'activité professionnelle, le manque de soutien psychologique de la mère allaitante, les préoccupations esthétiques et le retard de la montée laiteuse.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Allaitement maternel — Politique de l'allaitement (Facteurs de déclin)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__44\",\n       \"num\": \"45\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'enveloppement humide est un rôle propre de l'agent de santé dans la prise en charge de la fièvre chez l'enfant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les moyens physiques (dévêtir l'enfant, le faire boire, l'envelopper partiellement dans un linge mouillé, bain tiède) sont mis en œuvre par l'agent de santé sans prescription : ce sont des soins propres.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Fièvre de l'enfant — Rôles curatifs (Normalisation de la température : moyens physiques)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__45\",\n       \"num\": \"46\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Des crises convulsives subintrantes sans reprise de la conscience inter-critique réalisent un état de mal convulsif\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'état de mal convulsif est une crise qui dure plus de 30 minutes ou une succession de crises pendant plus de 30 minutes sans reprise de conscience entre les crises.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Convulsions de l'enfant — Introduction (Définition et limite du thème)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__46\",\n       \"num\": \"47\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hyperparasitémie supérieure à 4% chez le sujet immun est un critère clinique de gravité du paludisme grave\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'hyperparasitémie fait partie des critères de gravité du paludisme définis par l'OMS (critères révisés en 2000). Remarque : Le cours ne donne pas de seuil chiffré. En connaissances générales, le seuil de 4 % est retenu pour le sujet non immun ; de plus, c'est un critère biologique et non clinique.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Paludisme de l'enfant — Étude clinique (Paludisme grave : manifestations biologiques)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__47\",\n       \"num\": \"48\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"JL a 4 ans, il présente seulement une fièvre et 2 vomissements ce jour. Le TDR paludisme réalisé est positif. Le traitement à administrer est l'Artéméther injectable.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Il s'agit d'un paludisme simple sans signe de danger : le traitement est une combinaison à base d'artémisinine par voie orale (artésunate + amodiaquine). L'artéméther ou l'artésunate injectables sont réservés au paludisme grave. Remarque : Deux vomissements ne correspondent pas au signe de danger « vomit tout ».\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Paludisme de l'enfant — Rôles du soignant (Rôle de soins curatifs : 1re et 3e situations)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__48\",\n       \"num\": \"49\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le stress et le manque d'affection favorisent les vomissements du nourrisson\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Parmi les facteurs favorisants liés à l'environnement, le cours cite les conflits entre le père et la mère ; les vomissements psychogènes figurent parmi les causes de vomissements habituels.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Vomissements de l'enfant — Facteurs favorisants liés à l'environnement ; Diagnostic (Tableau n° II : causes des vomissements habituels)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__49\",\n       \"num\": \"50\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le temps de recoloration cutané supérieur à 3 secondes est un signe de bonne tolérance de la fièvre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Un temps de recoloration cutanée allongé (supérieur à 3 secondes) est un signe de mauvaise tolérance de la fièvre (mauvaise perfusion).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Fièvre de l'enfant — Diagnostic étiologique (Examen physique : signes de mauvaise tolérance)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__50\",\n       \"num\": \"51\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les téguments chauds et érythrosiques sont des signes de bonne tolérance de la fièvre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Une peau chaude et rouge traduit une bonne vasodilatation périphérique : la fièvre est bien tolérée. À l'inverse, pâleur, marbrures, extrémités froides et teint grisâtre sont des signes de mauvaise tolérance. Remarque : Les signes de bonne tolérance ne sont pas listés mot à mot dans le cours ; ils s'opposent aux signes de mauvaise tolérance.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Fièvre de l'enfant — Diagnostic étiologique (Examen physique : signes de mauvaise tolérance)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__51\",\n       \"num\": \"52\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le syndrome extrapyramidal qui survient chez l'enfant après administration de l'antiémétisant se traite avec du diazépam\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Faux ». Les antiémétiques (métoclopramide, métopimazine…) peuvent provoquer un syndrome extrapyramidal chez l'enfant.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Vomissements de l'enfant — Rôles de soins (Rôles curatifs : antiémétisants)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__52\",\n       \"num\": \"53\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson présentant une diarrhée aiguë sans signe de déshydratation boit avec avidité :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai ».\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Diagnostic de gravité (Tableau n°1 : classification) ; Livret de tableaux PCIMNE 0-5 ans, Évaluer la déshydratation\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__53\",\n       \"num\": \"54\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'Haemophilus influenzae est l'un des principaux germes responsables de la méningite bactérienne\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les méningites purulentes sont dues dans plus des deux tiers des cas au pneumocoque, à Haemophilus influenzae type b et au méningocoque.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Méningites bactériennes de l'enfant — Épidémiologie (Germes et résistance)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__54\",\n       \"num\": \"55\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant une fièvre aiguë, vous collaborez avec le médecin à la réalisation d'un tubage gastrique BK\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le tubage gastrique à la recherche du BK (tuberculose) fait partie des examens de la fièvre prolongée ou chronique, pas de la fièvre aiguë.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Fièvre de l'enfant — Diagnostic étiologique (Prescription d'examens : fièvre prolongée ou chronique) J4 Médecine · Chirurgie · Santé publique · Pédiatrie — 211 questions\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
